/* @lc app=leetcode id=3772 lang=kotlin */ class Solution { fun maxSubgraphScore(n: Int, edges: Array<IntArray>, good: IntArray): IntArray = edges.flatMap { (a, b) -> listOf(a to b, b to a) }.groupBy({ it.first }, { it.second }).let { g -> IntArray(n) { -1 }.also { it[0] = 0 }.let { par -> generateSequence(listOf(0)) { f -> f.flatMap { u -> g[u].orEmpty().filter { par[it] == -1 }.onEach { v -> par[v] = u } }.takeIf { it.isNotEmpty() } }.flatten().toList().let { order -> IntArray(n) { if (good[it] == 1) 1 else -1 }.let { w -> IntArray(n).also { dn -> order.reversed().forEach { v -> dn[v] = w[v] + g[v].orEmpty().filter { par[it] == v && it != 0 }.sumOf { maxOf(0, dn[it]) } } }.let { dn -> IntArray(n).also { tot -> tot[0] = dn[0] }.also { tot -> order.drop(1).forEach { c -> tot[c] = dn[c] + maxOf(0, tot[par[c]] - maxOf(0, dn[c])) } } } } } } } }